/* Small utilities                                                             */
/* -------------------------------------------------------------------------- */

/** True for a non-null, non-array object. */
function isObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** A finite number, or null. */
function finiteOrNull(value) {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

/** A non-negative integer count, or null. */
function countOrNull(value) {
  const number = finiteOrNull(value);
  if (number === null || number < 0) return null;
  return Math.trunc(number);
}

/** An ISO timestamp string, or null when the value is not a non-empty string. */
function isoOrNull(value) {
  return typeof value === "string" && value.trim() !== "" ? value : null;
}

/** Whole seconds from `nowMs` until an ISO timestamp, clamped at zero; null if unusable. */
function secondsUntil(iso, nowMs) {
  const target = iso === null ? NaN : Date.parse(iso);
  if (!Number.isFinite(target) || !Number.isFinite(nowMs)) return null;
  return Math.max(0, Math.floor((target - nowMs) / 1000));
}

/** Round to `digits` decimal places without ever returning -0. */
function roundTo(value, digits) {
  const factor = 10 ** digits;
  const rounded = Math.round(value * factor) / factor;
  return rounded === 0 ? 0 : rounded;
}

/** One-decimal percentage `part / total * 100`; zero total is 0 %. */
function sharePct(part, total) {
  if (!Number.isFinite(part) || !Number.isFinite(total) || total <= 0) return 0;
  return roundTo((part / total) * 100, 1);
}

/** Message off any throwable without losing plain `{ message }` carriers. */
function errorMessage(error) {
  if (error instanceof Error) return error.message;
  const message = error?.message;
  if (typeof message === "string" && message !== "") return message;
  return String(error);
}

/** Truncate a diagnostic string; callers never pass a secret here. */
function truncate(text, limit) {
  const value = typeof text === "string" ? text : String(text);
  return value.length <= limit ? value : `${value.slice(0, limit)}…`;
}

/** The first finite number in a candidate list, else the fallback. */
function firstFinite(candidates, fallback) {
  for (const candidate of candidates) {
    if (typeof candidate === "number" && Number.isFinite(candidate)) return candidate;
  }
  return fallback;
}

/** Resolve the DSH home directory the same way the Host does. */
function resolveDshHome(env = process.env) {
  const raw = env?.DSH_HOME;
  if (typeof raw === "string" && raw.trim() !== "") return raw.trim();
  return join(homedir(), ".dsh");
}

/** Safe, never-throwing logger call (the row must not throw into the Loader). */
function safeLog(ctx, level, message) {
  try {
    const logger = ctx?.logger;
    const method = logger?.[level];
    if (typeof method === "function") method.call(logger, message);
  } catch {
    /* logging is best effort */
  }
}

/* -------------------------------------------------------------------------- */
/* §4.6 — browser-trust fence                                                  */
/* -------------------------------------------------------------------------- */

/** Case-insensitive header read from a plain object or a fetch `Headers`. */
function readHeader(headers, wantedName) {
  if (headers === undefined || headers === null) return undefined;
  if (typeof headers.get === "function") {
    const found = headers.get(wantedName);
    return found === null || found === undefined ? undefined : String(found);
  }
  const wanted = wantedName.toLowerCase();
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() !== wanted) continue;
    const value = headers[key];
    if (value === undefined || value === null) return undefined;
    if (Array.isArray(value)) return value.length === 0 ? undefined : String(value[0]);
    return String(value);
  }
  return undefined;
}

/** Parse a bare `host` / `host:port` authority, or undefined when malformed. */
function parseAuthority(authority) {
  try {
    return new URL(`http://${authority}`);
  } catch {
    return undefined;
  }
}

/** Loopback hostname: `localhost`, `[::1]`, or any `127.0.0.0/8` literal (CONTRACT.md §4.6). */
function isLoopbackHostname(hostname) {
  if (hostname === "localhost" || hostname === "[::1]") return true;
  const parts = hostname.split(".");
  return (
    parts.length === 4 &&
    parts[0] === "127" &&
    parts.every((part) => /^\d{1,3}$/u.test(part) && Number(part) <= 255)
  );
}

/**
 * A `trustedHosts` entry matches when it is a port-less host naming the same
 * hostname, or an exact `host:port` authority.
 */
function isTrustedAuthority(hostUrl, trustedHosts) {
  for (const entry of trustedHosts) {
    if (typeof entry !== "string" || entry === "") continue;
    const entryUrl = parseAuthority(entry);
    if (entryUrl === undefined) continue;
    if (entryUrl.port === "") {
      if (entryUrl.hostname === hostUrl.hostname) return true;
    } else if (entryUrl.host === hostUrl.host) {
      return true;
    }
  }
  return false;
}

/**
 * Decide whether one request may reach a credits route (CONTRACT.md §4.6).
 *
 * 1. `Host` parses and its hostname is loopback OR matches a `trustedHosts`
 *    authority;
 * 2. `sec-fetch-site` is not `cross-site`;
 * 3. an attached `Origin`, when present, has the same hostname as `Host` — the
 *    literal `null` is an opaque origin and is refused.
 *
 * @param reqOrHeaders - a node `req` ({ headers, socket }), a plain headers
 *   object, or a fetch `Headers`.
 * @param trustedHosts - bare authorities, or a live `() => authorities` getter.
 * @returns true when the request is same-origin with this deployment.
 */
export function isTrustedRequest(reqOrHeaders, trustedHosts) {
  const headers =
    isObject(reqOrHeaders) && isObject(reqOrHeaders.headers) ? reqOrHeaders.headers : reqOrHeaders;

  const host = readHeader(headers, "host");
  if (host === undefined || host === "") return false;
  const hostUrl = parseAuthority(host);
  if (hostUrl === undefined) return false;

  let allowed;
  try {
    allowed = typeof trustedHosts === "function" ? trustedHosts() : trustedHosts;
  } catch {
    allowed = undefined;
  }
  const list = Array.isArray(allowed) ? allowed : [];
  if (!isLoopbackHostname(hostUrl.hostname) && !isTrustedAuthority(hostUrl, list)) return false;

  const site = readHeader(headers, "sec-fetch-site");
  if (typeof site === "string" && site.trim().toLowerCase() === "cross-site") return false;

  const origin = readHeader(headers, "origin");
  if (origin === undefined || origin === "") return true;
  if (origin === "null") return false;
  let originUrl;
  try {
    originUrl = new URL(origin);
  } catch {
    return false;
  }
  return originUrl.hostname === hostUrl.hostname;
}

/**
 * The deployment's trusted authorities, read per request from the live sources
 * this DSH provides (CONTRACT.md §4.6). Every lookup is structural and guarded:
 * injecting any of these would park the row on an engine that lacks it, and a
 * throwing lookup is not trust.
 *
 * @param ctx - host plugin context (only `ctx.get` is touched).
 * @returns bare authorities (`host` or `host:port`), deduped; never throws.
 */
function deploymentTrustedHosts(ctx) {
  const list = [];
  const push = (value) => {
    if (!Array.isArray(value)) return;
    for (const entry of value) {
      if (typeof entry === "string" && entry !== "" && !list.includes(entry)) list.push(entry);
    }
  };
  for (const serviceName of ["webRuntime", "webStartup", "connection"]) {
    try {
      push(ctx?.get?.(serviceName)?.trustedHosts);
    } catch {
      /* an absent or withheld service is not trust */
    }
  }
  return list;
}

/* -------------------------------------------------------------------------- */
/* §3 — credential resolution                                                  */
/* -------------------------------------------------------------------------- */

/**
 * Decode one YAML/`.env` scalar: strip one layer of quotes, or (unquoted) drop a
 * trailing ` # comment`. Returns "" when the scalar is empty.
 */
function decodeScalar(rawValue) {
  const value = typeof rawValue === "string" ? rawValue.trim() : "";
  if (value === "") return "";
  const first = value[0];
  if (first === '"' || first === "'") {
    const closing = value.indexOf(first, 1);
    if (closing !== -1) return value.slice(1, closing);
    // Unterminated quote: fall through to the unquoted handling.
  }
  const commentAt = value.search(/\s+#/u);
  return (commentAt === -1 ? value : value.slice(0, commentAt)).trim();
}

/**
 * Parse the `refs:` mapping out of a DSH credential store document
 * (`$DSH_HOME/.credentials.yaml`) without a YAML dependency.
 *
 * Only the top-level `refs:` block is read; the `records:` block holds unrelated
 * credentials and is deliberately ignored. Values lose one layer of quotes, as
 * CONTRACT.md §3 specifies.
 *
 * @param text - raw `.credentials.yaml` text.
 * @returns a plain object mapping credential ref name -> secret.
 */
export function parseCredentialRefs(text) {
  const refs = {};
  if (typeof text !== "string" || text === "") return refs;

  let inRefs = false;
  for (const rawLine of text.split(/\r?\n/u)) {
    if (!inRefs) {
      const match = /^refs\s*:\s*(.*)$/u.exec(rawLine);
      if (match === null) continue;
      inRefs = true;
      const inline = match[1].trim();
      if (inline !== "" && inline !== "{}" && inline !== "~" && inline !== "null") {
        // Best-effort flow map: { KEY: value, OTHER: 'value' }.
        const entry = /([A-Za-z_][A-Za-z0-9_]*)\s*:\s*(?:"([^"]*)"|'([^']*)'|([^,}]*))/gu;
        let flow;
        while ((flow = entry.exec(inline)) !== null) {
          const flowKey = flow[1];
          const flowValue = decodeScalar(flow[2] ?? flow[3] ?? flow[4] ?? "");
          if (flowValue !== "") refs[flowKey] = flowValue;
        }
      }
      continue;
    }

    // Inside `refs:`: blank lines and full-line comments belong to the block.
    if (/^\s*(?:#.*)?$/u.test(rawLine)) continue;
    const indent = rawLine.match(/^\s*/u)[0].length;
    if (indent === 0) break; // the next top-level key ends the block

    const match = /^\s+([^:#][^:]*?)\s*:\s*(.*)$/u.exec(rawLine);
    if (match === null) continue;
    const key = decodeScalar(match[1]);
    if (key === "") continue;
    const value = decodeScalar(match[2]);
    if (value !== "") refs[key] = value;
  }
  return refs;
}

/**
 * Parse `NAME=value` lines out of a `.env` file. `export ` prefixes, blank
 * lines and `#` comments are ignored; values lose one layer of quotes.
 *
 * @param text - raw `.env` file text.
 * @returns a plain object mapping variable name -> value.
 */
export function parseDotEnv(text) {
  const variables = {};
  if (typeof text !== "string" || text === "") return variables;
  for (const rawLine of text.split(/\r?\n/u)) {
    let line = rawLine.trim();
    if (line === "" || line.startsWith("#")) continue;
    if (line.startsWith("export ")) line = line.slice("export ".length).trim();
    const equalsAt = line.indexOf("=");
    if (equalsAt <= 0) continue;
    const key = line.slice(0, equalsAt).trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/u.test(key)) continue;
    const value = decodeScalar(line.slice(equalsAt + 1));
    if (value !== "") variables[key] = value;
  }
  return variables;
}

/** A usable secret string, or null (never trims interior characters). */
function cleanSecret(value) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed === "" ? null : trimmed;
}

/** Default synchronous file reader for `resolveApiKey`; missing/unreadable -> null. */
function readTextFile(path) {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return null;
  }
}

/**
 * Resolve the Ollama Cloud API key through the frozen credential chain
 * (CONTRACT.md §3). The returned key is the secret itself — callers must never
 * log it or write it to disk; `source` is safe to report.
 *
 * Order: `config.apiKey` -> `$DSH_HOME/.credentials.yaml` refs[apiKeyEnv] ->
 * `process.env[apiKeyEnv]` -> `$DSH_HOME/.env` -> `<cwd>/.env`. The credential
 * store (what the DSH GUI saves) deliberately wins over a stale launch
 * environment, matching the Host's own `dsh-credentials-local` seam.
 *
 * @param options - `{ apiKey?, apiKeyEnv?, env?, dshHome?, cwd?, readFile? }`.
 * @returns `{ key: string|null, source }`.
 */
export function resolveApiKey(options = {}) {
  const source = isObject(options) ? options : {};
  const env = isObject(source.env) ? source.env : process.env;
  const apiKeyEnv =
    typeof source.apiKeyEnv === "string" && source.apiKeyEnv.trim() !== ""
      ? source.apiKeyEnv.trim()
      : DEFAULT_API_KEY_ENV;
  const dshHome =
    typeof source.dshHome === "string" && source.dshHome.trim() !== ""
      ? source.dshHome.trim()
      : resolveDshHome(env);
  let cwd = null;
  if (typeof source.cwd === "string" && source.cwd.trim() !== "") {
    cwd = source.cwd.trim();
  } else {
    try {
      cwd = process.cwd();
    } catch {
      cwd = null;
    }
  }
  const readFile = typeof source.readFile === "function" ? source.readFile : readTextFile;

  const literal = cleanSecret(source.apiKey);
  if (literal !== null) return { key: literal, source: "config" };

  // The credential store wins over the launch environment: a key saved through
  // the DSH GUI must not be shadowed by a stale exported variable.
  const credentialsText = readFile(join(dshHome, ".credentials.yaml"));
  if (typeof credentialsText === "string" && credentialsText !== "") {
    const refs = parseCredentialRefs(credentialsText);
    const fromRefs = cleanSecret(refs[apiKeyEnv]);
    if (fromRefs !== null) return { key: fromRefs, source: "credentials-file" };
  }

  const fromEnv = cleanSecret(env?.[apiKeyEnv]);
  if (fromEnv !== null) return { key: fromEnv, source: "env" };

  const dshEnvText = readFile(join(dshHome, ".env"));
  if (typeof dshEnvText === "string" && dshEnvText !== "") {
    const fromDshEnv = cleanSecret(parseDotEnv(dshEnvText)[apiKeyEnv]);
    if (fromDshEnv !== null) return { key: fromDshEnv, source: "dsh-env-file" };
  }

  if (cwd !== null) {
    const cwdEnvText = readFile(join(cwd, ".env"));
    if (typeof cwdEnvText === "string" && cwdEnvText !== "") {
      const fromCwdEnv = cleanSecret(parseDotEnv(cwdEnvText)[apiKeyEnv]);
      if (fromCwdEnv !== null) return { key: fromCwdEnv, source: "cwd-env-file" };
    }
  }

  return { key: null, source: "missing" };
}

/* -------------------------------------------------------------------------- */
/* §4.1 — balance summary                                                      */
/* -------------------------------------------------------------------------- */

/** One session/weekly window from an upstream `included` block. */
function summarizeWindow(source, nowMs) {
  const window = isObject(source) ? source : {};
  const resetsAt = isoOrNull(window.resets_at);
  return {
    remainingPercent: finiteOrNull(window.remaining_percent),
    resetsAt,
    resetInSec: secondsUntil(resetsAt, nowMs),
  };
}

/**
 * Normalize one `/api/balance` document into the §4.1 `balance` object.
 *
 * Two upstream plans are understood (CONTRACT.md measured facts):
 *   - legacy: `included.session` / `included.weekly` with `remaining_percent` +
 *     `resets_at`, plus `purchased.balance_usd`;
 *   - credit-metered: `included.balance_usd` / `included.allowance_usd` with a
 *     billing `period`; `session`/`weekly` are then emitted with null values.
 *
 * @param raw - `/api/balance` JSON.
 * @param nowMsOrOptions - a number (nowMs) or `{ nowMs?, asOf? }`.
 * @returns `{ asOf, plan, session, weekly, included, purchased }`.
 */
export function summarizeBalance(raw, nowMsOrOptions) {
  const options = isObject(nowMsOrOptions) ? nowMsOrOptions : {};
  const nowMs = isObject(nowMsOrOptions)
    ? firstFinite([options.nowMs], Date.now())
    : firstFinite([nowMsOrOptions], Date.now());
  // A caller that does not state the observation instant gets "now": the pure
  // helper is a summary taken at this moment. The routes always pass `asOf`
  // explicitly (including a literal null), so a stale persisted snapshot can
  // never be relabelled as fresh here.
  const asOf = Object.prototype.hasOwnProperty.call(options, "asOf")
    ? isoOrNull(options.asOf)
    : new Date(nowMs).toISOString();
  const document = isObject(raw) ? raw : {};
  const includedRaw = isObject(document.included) ? document.included : null;
  const purchasedRaw = isObject(document.purchased) ? document.purchased : null;

  const creditsPlan =
    includedRaw !== null &&
    (finiteOrNull(includedRaw.balance_usd) !== null ||
      finiteOrNull(includedRaw.allowance_usd) !== null);
  const legacyPlan =
    includedRaw !== null && (isObject(includedRaw.session) || isObject(includedRaw.weekly));
  const plan = creditsPlan ? "credits" : legacyPlan ? "legacy" : "unknown";

  let included = null;
  if (creditsPlan && includedRaw !== null) {
    const period = isObject(includedRaw.period) ? includedRaw.period : {};
    const until = isoOrNull(period.until);
    included = {
      balanceUsd: finiteOrNull(includedRaw.balance_usd),
      allowanceUsd: finiteOrNull(includedRaw.allowance_usd),
      period: {
        from: isoOrNull(period.from),
        until,
        resetInSec: secondsUntil(until, nowMs),
      },
    };
  }

  return {
    asOf,
    plan,
    session: summarizeWindow(includedRaw?.session, nowMs),
    weekly: summarizeWindow(includedRaw?.weekly, nowMs),
    included,
    purchased: { balanceUsd: finiteOrNull(purchasedRaw?.balance_usd) },
  };
}

/* -------------------------------------------------------------------------- */
/* §4.1 — usage summary                                                        */
/* -------------------------------------------------------------------------- */

/** Read upstream's folded-remaining entry (`remainder`) as `{ requests, usageUsd }`. */
function readRemainder(value) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return { requests: Math.max(0, Math.trunc(value)), usageUsd: null };
  }
  if (isObject(value)) {
    const requests = countOrNull(value.request_count ?? value.requests ?? value.count);
    if (requests === null) return null;
    return { requests, usageUsd: finiteOrNull(value.usage_usd ?? value.usageUsd) };
  }
  if (Array.isArray(value)) {
    let requests = 0;
    let allUsd = true;
    let usdTotal = 0;
    for (const group of value) {
      if (!isObject(group)) continue;
      const count = countOrNull(group.request_count ?? group.requests ?? group.count);
      if (count === null) continue;
      requests += count;
      const usd = finiteOrNull(group.usage_usd ?? group.usageUsd);
      if (usd === null) allUsd = false;
      else usdTotal += usd;
    }
    return requests > 0 ? { requests, usageUsd: allUsd ? usdTotal : null } : null;
  }
  return null;
}

/** One upstream model group, defensively normalized. */
function readModelGroup(group) {
  if (!isObject(group)) return null;
  const requests = countOrNull(group.request_count ?? group.requests ?? group.count);
  if (requests === null) return null;
  const model = typeof group.model === "string" && group.model.trim() !== "" ? group.model.trim() : "unknown";
  return { model, requests, usageUsd: finiteOrNull(group.usage_usd ?? group.usageUsd) };
}

/**
 * Normalize a totals (or bucket-totals) block: request count, USD total when
 * upstream reports one, and the per-model list with one-decimal `sharePct`.
 *
 * The upstream list is at most 10 models; anything beyond that (or an explicit
 * `remainder`) is folded into one trailing `{ model: '__other__' }` entry
 * (CONTRACT.md §4.1 rules).
 */
function summarizeUsageTotals(source, explicitRequests) {
  const totals = isObject(source) ? source : {};
  const groups = Array.isArray(totals.groups) ? totals.groups : [];
  const remainder = readRemainder(totals.remainder);

  const models = [];
  for (const group of groups) {
    const model = readModelGroup(group);
    if (model !== null) models.push(model);
  }
  models.sort((left, right) => right.requests - left.requests || left.model.localeCompare(right.model));

  let totalRequests = countOrNull(explicitRequests);
  if (totalRequests === null) totalRequests = countOrNull(totals.request_count ?? totals.requests);
  if (totalRequests === null) {
    let sum = remainder?.requests ?? 0;
    for (const model of models) sum += model.requests;
    totalRequests = sum;
  }

  const entries = models.map((model) => ({
    model: model.model,
    requests: model.requests,
    sharePct: sharePct(model.requests, totalRequests),
    usageUsd: model.usageUsd,
  }));

  const folded = [];
  if (remainder !== null && remainder.requests > 0) {
    folded.push({ model: "__other__", requests: remainder.requests, usageUsd: remainder.usageUsd });
  }
  while (entries.length > 10) {
    const extra = entries.pop();
    if (extra !== undefined) folded.push(extra);
  }
  if (folded.length > 0) {
    let requests = 0;
    let usd = 0;
    let allUsd = true;
    for (const entry of folded) {
      requests += entry.requests;
      if (typeof entry.usageUsd === "number" && Number.isFinite(entry.usageUsd)) usd += entry.usageUsd;
      else allUsd = false;
    }
    entries.push({
      model: "__other__",
      requests,
      sharePct: sharePct(requests, totalRequests),
      usageUsd: allUsd ? roundTo(usd, 4) : null,
    });
  }

  let usageUsd = finiteOrNull(totals.usage_usd ?? totals.usageUsd);
  if (usageUsd === null && entries.length > 0) {
    let summed = 0;
    let allUsd = true;
    for (const entry of entries) {
      if (typeof entry.usageUsd === "number" && Number.isFinite(entry.usageUsd)) summed += entry.usageUsd;
      else allUsd = false;
    }
    // Legacy plans report request_count only: never fabricate a USD figure.
    usageUsd = allUsd ? roundTo(summed, 4) : null;
  }

  return { requests: totalRequests, usageUsd, models: entries };
}

/** Normalize one upstream bucket; `fallbackFrom`/`fallbackUntil` come from the grid. */
function summarizeUsageBucket(bucket, fallbackFrom, fallbackUntil) {
  const source = isObject(bucket) ? bucket : {};
  const totalsSource = isObject(source.totals) ? source.totals : source;
  const explicit = countOrNull(source.request_count ?? source.requests);
  const totals = summarizeUsageTotals(totalsSource, explicit);
  return {
    from: isoOrNull(source.from) ?? fallbackFrom ?? null,
    until: isoOrNull(source.until) ?? fallbackUntil ?? null,
    partial: source.partial === true,
    requests: totals.requests,
    models: totals.models,
  };
}

/** Granularity step in ms for the zero-fill grid. */
function stepMsFor(granularity) {
  if (granularity === "hour") return 60 * 60 * 1000;
  if (granularity === "day") return 24 * 60 * 60 * 1000;
  return null;
}

/**
 * Chronological, zero-filled bucket list (CONTRACT.md §4.1): walk the
 * `from` -> `until` grid at the response granularity and emit an empty bucket
 * for every grid slot the upstream document does not cover. A sparse upstream
 * document therefore still renders a full chart.
 */
function summarizeBuckets(rawBuckets, from, until, granularity) {
  const listed = Array.isArray(rawBuckets) ? rawBuckets.filter(isObject) : [];
  const stepMs = stepMsFor(granularity);
  const startMs = from === null ? NaN : Date.parse(from);
  const endMs = until === null ? NaN : Date.parse(until);

  if (stepMs === null || !Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
    return listed.map((bucket) => summarizeUsageBucket(bucket, null, null));
  }

  const byStart = new Map();
  for (const bucket of listed) {
    const bucketFrom = isoOrNull(bucket.from);
    if (bucketFrom === null) continue;
    const key = Date.parse(bucketFrom);
    if (Number.isFinite(key) && !byStart.has(key)) byStart.set(key, bucket);
  }

  const buckets = [];
  for (let slot = startMs; slot < endMs; slot += stepMs) {
    const slotFrom = new Date(slot).toISOString();
    const slotUntil = new Date(Math.min(slot + stepMs, endMs)).toISOString();
    const matched = byStart.get(slot);
    if (matched !== undefined) {
      buckets.push(summarizeUsageBucket(matched, slotFrom, slotUntil));
    } else {
      buckets.push({ from: slotFrom, until: slotUntil, partial: false, requests: 0, models: [] });
    }
  }
  return buckets;
}

/**
 * Normalize one `/api/usage?range=...&group_by=model` document into the §4.1
 * `UsageRange` shape. Legacy plans report `request_count` only, so `usageUsd`
 * stays null instead of being guessed (CONTRACT.md §8).
 *
 * @param raw - `/api/usage?...` JSON.
 * @returns the UsageRange, or null when the document is not an object.
 */
export function summarizeUsage(raw) {
  if (!isObject(raw)) return null;
  const range = typeof raw.range === "string" && raw.range !== "" ? raw.range : "24h";
  const granularity =
    typeof raw.granularity === "string" && raw.granularity !== ""
      ? raw.granularity
      : range === "24h"
        ? "hour"
        : "day";
  const from = isoOrNull(raw.from);
  const until = isoOrNull(raw.until);
  return {
    range,
    granularity,
    from,
    until,
    totals: summarizeUsageTotals(isObject(raw.totals) ? raw.totals : raw, null),
    buckets: summarizeBuckets(raw.buckets, from, until, granularity),
  };
}

/* -------------------------------------------------------------------------- */
/* §4.2 — status summary                                                       */
/* -------------------------------------------------------------------------- */

/** The compact usage block §4.2 emits for one range (`hourly` / `weekly`). */
function statusUsageBlock(range) {
  const empty = { requests: 0, topModel: null, topModelRequests: 0 };
  if (!isObject(range)) return empty;
  const totals = isObject(range.totals) ? range.totals : range;
  const requests = countOrNull(totals.requests ?? totals.request_count) ?? 0;
  const models = Array.isArray(totals.models) ? totals.models.filter(isObject) : [];
  const top =
    models.find((model) => model.model !== "__other__") ??
    models[0] ??
    null;
  return {
    requests,
    topModel: top !== null && typeof top.model === "string" ? top.model : null,
    topModelRequests: top === null ? 0 : countOrNull(top.requests) ?? 0,
  };
}

/** A §4.2 window object, recomputing `resetInSec` against `nowMs` when possible. */
function statusWindow(window, nowMs) {
  const source = isObject(window) ? window : {};
  const resetsAt = isoOrNull(source.resetsAt);
  return {
    remainingPercent: finiteOrNull(source.remainingPercent),
    resetsAt,
    resetInSec: finiteOrNull(source.resetInSec) ?? secondsUntil(resetsAt, nowMs),
  };
}

/**
 * Normalize the two accepted `summarizeStatus` call shapes into one internal
 * view: the aggregate `{ balance, usage, poll, config, nowMs }` form and the
 * `(balanceSummary, options)` form.
 */
function normalizeStatusArguments(stateOrBalance, configOrOptions) {
  let state = isObject(stateOrBalance) ? stateOrBalance : null;
  let options = isObject(configOrOptions) ? configOrOptions : {};

  if (state !== null && isObject(state.balance) && !("plan" in state) && !("session" in state)) {
    const aggregate = state;
    options = {
      ...options,
      usage: isObject(options.usage) ? options.usage : aggregate.usage,
      poll: isObject(options.poll) ? options.poll : aggregate.poll,
      config: isObject(options.config) ? options.config : aggregate.config,
      thresholds: isObject(options.thresholds) ? options.thresholds : aggregate.thresholds,
      nowMs: options.nowMs ?? aggregate.nowMs,
      status: options.status ?? aggregate.status,
    };
    state = aggregate.balance;
  }

  let balance = null;
  if (isObject(state)) {
    if (state.plan !== undefined || state.asOf !== undefined || state.session !== undefined) {
      balance = state;
    } else if (state.included !== undefined || state.purchased !== undefined) {
      // A raw `/api/balance` document was handed over: summarize it in place.
      balance = summarizeBalance(state, { nowMs: options.nowMs });
    }
  }

  const config = isObject(options.config) ? options.config : {};
  const thresholds = isObject(options.thresholds) ? options.thresholds : {};
  const poll = isObject(options.poll) ? options.poll : {};
  const nowMs = firstFinite([options.nowMs], Date.now());
  const usage = isObject(options.usage) ? options.usage : {};
  const lastError =
    typeof options.lastError === "string"
      ? options.lastError
      : typeof poll.lastError === "string"
        ? poll.lastError
        : null;
  const missingCredential =
    options.status === "no-credential" ||
    options.missingCredential === true ||
    lastError === MISSING_CREDENTIAL;

  return {
    balance,
    config,
    thresholds,
    poll,
    usage,
    nowMs,
    lastError,
    sessionPct: firstFinite(
      [thresholds.sessionPct, options.sessionPct, config.lowSessionPct, options.lowSessionPct],
      DEFAULT_LOW_SESSION_PCT,
    ),
    weeklyPct: firstFinite(
      [thresholds.weeklyPct, options.weeklyPct, config.lowWeeklyPct, options.lowWeeklyPct],
      DEFAULT_LOW_WEEKLY_PCT,
    ),
    intervalMin: firstFinite(
      [options.intervalMin, config.pollIntervalMin, poll.intervalMin],
      DEFAULT_POLL_INTERVAL_MIN,
    ),
    lastPollAt: isoOrNull(options.lastPollAt) ?? isoOrNull(poll.lastPollAt),
    missingCredential,
  };
}

/**
 * Build the compact, stable §4.2 status document from the same facts the
 * overview route emits.
 *
 * @param state - `{ balance, usage, poll, config?, nowMs? }` where `balance` is
 *   a `summarizeBalance` result, `usage` is keyed `'24h'`/`'7d'`/`'30d'`, and
 *   `poll` is `{ intervalMin, lastPollAt, lastError }`.
 * @param configOrOptions - optional threshold/config overrides.
 * @returns the §4.2 document (`ok:true`), or `{ ok:false, status, message }`
 *   when there is no balance snapshot yet.
 */
export function summarizeStatus(stateOrBalance, configOrOptions) {
  const view = normalizeStatusArguments(stateOrBalance, configOrOptions);
  if (view.balance === null) {
    const missing = view.missingCredential;
    return {
      ok: false,
      status: missing ? "no-credential" : "no-data",
      message: missing
        ? "No Ollama Cloud API credential was found (set OLLAMA_CLOUD_API_KEY or add it to $DSH_HOME/.credentials.yaml)."
        : view.lastError !== null
          ? `No Ollama Cloud data yet: ${view.lastError}`
          : "Waiting for the first Ollama Cloud poll to finish.",
    };
  }

  const balance = view.balance;
  const session = statusWindow(balance.session, view.nowMs);
  const weekly = statusWindow(balance.weekly, view.nowMs);
  const thresholds = { sessionPct: view.sessionPct, weeklyPct: view.weeklyPct };

  let included = null;
  if (isObject(balance.included)) {
    included = {
      balanceUsd: finiteOrNull(balance.included.balanceUsd),
      allowanceUsd: finiteOrNull(balance.included.allowanceUsd),
      resetInSec:
        finiteOrNull(balance.included.resetInSec) ??
        finiteOrNull(isObject(balance.included.period) ? balance.included.period.resetInSec : null),
    };
  }

  const sessionLow =
    session.remainingPercent !== null && session.remainingPercent <= thresholds.sessionPct;
  const weeklyLow =
    weekly.remainingPercent !== null && weekly.remainingPercent <= thresholds.weeklyPct;
  const creditsLow =
    balance.plan === "credits" && included !== null && included.balanceUsd !== null
      ? included.balanceUsd <= 0
      : null;

  return {
    ok: true,
    asOf: isoOrNull(balance.asOf),
    plan: balance.plan ?? "unknown",
    windows: { session, weekly },
    included,
    thresholds,
    low: {
      session: sessionLow,
      weekly: weeklyLow,
      any: creditsLow !== null ? creditsLow : sessionLow || weeklyLow,
    },
    usage: {
      hourly: statusUsageBlock(view.usage["24h"] ?? view.usage.hourly),
      weekly: statusUsageBlock(view.usage["7d"] ?? view.usage.weekly),
    },
    poll: {
      intervalMin: view.intervalMin,
      lastPollAt: view.lastPollAt,
      lastError: view.lastError,
    },
  };
}

/* -------------------------------------------------------------------------- */
/* §3/§4.5 — config validation                                                 */
/* -------------------------------------------------------------------------- */

/** Build the default effective config for a given DSH home. */
function defaultConfig(dshHome) {
  return {
    apiBase: DEFAULT_API_BASE,
    apiKeyEnv: DEFAULT_API_KEY_ENV,
    pollIntervalMin: DEFAULT_POLL_INTERVAL_MIN,
    lowSessionPct: DEFAULT_LOW_SESSION_PCT,
    lowWeeklyPct: DEFAULT_LOW_WEEKLY_PCT,
    stateDir: join(dshHome, "ollama-credits"),
  };
}

/** One BAD_CONFIG envelope. */
function badConfig(message) {
  return { ok: false, error: "BAD_CONFIG", message };
}

/** Copy the known config keys off a previously validated base object. */
function copyKnownConfigFields(base) {
  const out = {};
  for (const key of [
    "apiBase",
    "apiKeyEnv",
    "apiKey",
    "pollIntervalMin",
    "lowSessionPct",
    "lowWeeklyPct",
    "stateDir",
  ]) {
    if (base[key] !== undefined) out[key] = base[key];
  }
  return out;
}

/**
 * Validate and normalize the row config (CONTRACT.md §3 defaults) or a
 * POST /config patch (CONTRACT.md §4.5).
 *
 * Every field is optional. Unknown keys are ignored. `pollIntervalMin` must be
 * an integer 1–60; `lowSessionPct`/`lowWeeklyPct` must be finite numbers 0–100.
 *
 * @param raw - the config/patch object.
 * @param options - `{ base?, dshHome? }`.
 * @returns `{ ok:true, config }` (the full effective config) or a BAD_CONFIG
 *   envelope.
 */
export function validateConfig(raw, options = {}) {
  const settings = isObject(options) ? options : {};
  const dshHome =
    typeof settings.dshHome === "string" && settings.dshHome.trim() !== ""
      ? settings.dshHome.trim()
      : resolveDshHome();
  const config = defaultConfig(dshHome);
  if (isObject(settings.base)) Object.assign(config, copyKnownConfigFields(settings.base));

  const input = raw === undefined || raw === null ? {} : raw;
  if (!isObject(input)) return badConfig("config must be a JSON object");

  if (input.apiBase !== undefined) {
    if (typeof input.apiBase !== "string" || input.apiBase.trim() === "") {
      return badConfig("apiBase must be a non-empty string");
    }
    const normalized = input.apiBase.trim().replace(/\/+$/u, "");
    let parsed;
    try {
      parsed = new URL(normalized);
    } catch {
      return badConfig("apiBase must be an absolute http(s) URL");
    }
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
      return badConfig("apiBase must be an absolute http(s) URL");
    }
    config.apiBase = normalized;
  }

  if (input.apiKeyEnv !== undefined) {
    if (typeof input.apiKeyEnv !== "string" || input.apiKeyEnv.trim() === "") {
      return badConfig("apiKeyEnv must be a non-empty string");
    }
    config.apiKeyEnv = input.apiKeyEnv.trim();
  }

  if (input.apiKey !== undefined) {
    if (input.apiKey === null || input.apiKey === "") {
      delete config.apiKey;
    } else if (typeof input.apiKey !== "string") {
      return badConfig("apiKey must be a string");
    } else {
      config.apiKey = input.apiKey;
    }
  }

  if (input.pollIntervalMin !== undefined) {
    if (
      typeof input.pollIntervalMin !== "number" ||
      !Number.isSafeInteger(input.pollIntervalMin) ||
      input.pollIntervalMin < 1 ||
      input.pollIntervalMin > 60
    ) {
      return badConfig("pollIntervalMin must be an integer between 1 and 60");
    }
    config.pollIntervalMin = input.pollIntervalMin;
  }

  if (input.lowSessionPct !== undefined) {
    if (
      typeof input.lowSessionPct !== "number" ||
      !Number.isFinite(input.lowSessionPct) ||
      input.lowSessionPct < 0 ||
      input.lowSessionPct > 100
    ) {
      return badConfig("lowSessionPct must be a number between 0 and 100");
    }
    config.lowSessionPct = input.lowSessionPct;
  }

  if (input.lowWeeklyPct !== undefined) {
    if (
      typeof input.lowWeeklyPct !== "number" ||
      !Number.isFinite(input.lowWeeklyPct) ||
      input.lowWeeklyPct < 0 ||
      input.lowWeeklyPct > 100
    ) {
      return badConfig("lowWeeklyPct must be a number between 0 and 100");
    }
    config.lowWeeklyPct = input.lowWeeklyPct;
  }

  if (input.stateDir !== undefined) {
    if (typeof input.stateDir !== "string" || input.stateDir.trim() === "") {
      return badConfig("stateDir must be a non-empty string");
    }
    config.stateDir = input.stateDir.trim();
  }

  return { ok: true, config };
}

/* -------------------------------------------------------------------------- */
/* §3 — persistence (atomic, synchronous, best effort)                         */
/* -------------------------------------------------------------------------- */

/**
 * Load a previously persisted state document. Any failure (missing file,
 * invalid JSON, wrong shape) reads as "no persisted state".
 */
function loadStateFile(statePath) {
  try {
    const text = readFileSync(statePath, "utf8");
    const parsed = JSON.parse(text);
    return isObject(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

/**
 * Atomically write JSON state: unique temp file -> fsync -> rename, so a reader
 * sees either the old document or the complete new one, never a torn file.
 * Failure degrades silently — persistence is a cache, not the source of truth.
 */
function writeStateFile(statePath, document) {
  const tempPath = `${statePath}.${process.pid}.${Date.now()}.tmp`;
  try {
    mkdirSync(dirname(statePath), { recursive: true });
    const handle = openSync(tempPath, "w");
    try {
      writeSync(handle, JSON.stringify(document, null, 1));
      fsyncSync(handle);
    } finally {
      closeSync(handle);
    }
    renameSync(tempPath, statePath);
  } catch {
    try {
      unlinkSync(tempPath);
    } catch {
      /* nothing to remove */
    }
  }
}

/* -------------------------------------------------------------------------- */
/* §3 — upstream requests                                                      */
/* -------------------------------------------------------------------------- */

/** Build one upstream URL without a trailing slash on the configured base. */
function apiUrl(apiBase, path) {
  return `${String(apiBase).replace(/\/+$/u, "")}${path}`;
}

/** Build the `group_by=model` usage URL for one range. */
function usageUrl(apiBase, range) {
  return apiUrl(apiBase, `/api/usage?range=${encodeURIComponent(range)}&group_by=model`);
}

/** A short, safe diagnostic from an upstream error body (never the request). */
function upstreamDetail(body) {
  if (!isObject(body)) return "";
  const raw =
    typeof body.error === "string"
      ? body.error
      : typeof body.message === "string"
        ? body.message
        : typeof body.error_description === "string"
          ? body.error_description
          : "";
  return truncate(raw.replace(/\s+/gu, " ").trim(), 120);
}

/**
 * GET one JSON document from the Ollama Cloud API with the frozen headers,
 * a 10 s timeout, and an optional external abort signal (disposal).
 */
async function fetchJsonDocument(url, key, externalSignal) {
  const timeout = AbortSignal.timeout(POLL_TIMEOUT_MS);
  const signal =
    typeof AbortSignal.any === "function" && externalSignal !== undefined && externalSignal !== null
      ? AbortSignal.any([timeout, externalSignal])
      : timeout;

  let response;
  try {
    response = await fetch(url, {
      method: "GET",
      headers: {
        authorization: `Bearer ${key}`,
        "user-agent": USER_AGENT,
        accept: "application/json",
      },
      signal,
    });
  } catch (error) {
    throw new Error(`request to ${url} failed: ${errorMessage(error)}`);
  }

  let body = null;
  try {
    body = await response.json();
  } catch {
    body = null;
  }
  if (!response.ok) {
    const detail = upstreamDetail(body);
    throw new Error(
      `Ollama Cloud API returned HTTP ${response.status}${detail === "" ? "" : ` (${detail})`}`,
    );
  }
  if (!isObject(body)) throw new Error("Ollama Cloud API returned a non-object JSON body");
  return body;
}

/* -------------------------------------------------------------------------- */
/* Service — poller + snapshot                                                 */
/* -------------------------------------------------------------------------- */

/** Small fixed interval floor so a hand-edited state file cannot spin the poller. */
const MIN_INTERVAL_MS = 60_000;

/**
 * The row's runtime: credential resolution, the non-overlapping poll cycle,
 * the last good snapshot, its atomic persistence, and the read views the
 * routes serve. One instance per `apply`.
 */
class OllamaCreditsService {
  constructor(ctx, config, statePath, persisted) {
    this.ctx = ctx;
    this.config = config;
    this.statePath = statePath;

    this.balanceRaw = null;
    this.usageRaw = null;
    this.snapshotAt = null;
    this.lastPollAt = null;
    this.lastPollOk = false;
    this.lastError = null;
    this.credentialSource = undefined;

    this.inFlight = false;
    this.cyclePromise = undefined;
    this.cycleAbort = null;
    this.timer = undefined;
    this.disposed = false;

    this.loadPersistedSnapshot(persisted);
  }

  /** Adopt the persisted snapshot (CONTRACT.md §3: a restart shows known facts). */
  loadPersistedSnapshot(persisted) {
    if (!isObject(persisted)) return;
    const snapshot = isObject(persisted.snapshot) ? persisted.snapshot : {};
    this.snapshotAt = isoOrNull(snapshot.asOf);
    this.balanceRaw = isObject(snapshot.balance) ? snapshot.balance : null;
    this.usageRaw = isObject(snapshot.usage) ? snapshot.usage : null;
    const poll = isObject(snapshot.poll) ? snapshot.poll : {};
    this.lastPollAt = isoOrNull(poll.lastPollAt);
    this.lastPollOk = poll.lastPollOk === true;
    this.lastError = typeof poll.lastError === "string" ? poll.lastError : null;
  }

  /** The three user-settable settings, as every route reports them. */
  publicConfig() {
    return {
      pollIntervalMin: this.config.pollIntervalMin,
      lowSessionPct: this.config.lowSessionPct,
      lowWeeklyPct: this.config.lowWeeklyPct,
    };
  }

  /** Poll cadence in ms (integer minutes; >= 1 minute by construction). */
  intervalMs() {
    const minutes = firstFinite([this.config.pollIntervalMin], DEFAULT_POLL_INTERVAL_MIN);
    return Math.max(MIN_INTERVAL_MS, Math.trunc(minutes) * 60_000);
  }

  /** Resolve (and remember only) the credential source for the no-data status text. */
  refreshCredentialSource() {
    try {
      this.credentialSource = resolveApiKey({
        apiKey: this.config.apiKey,
        apiKeyEnv: this.config.apiKeyEnv,
      }).source;
    } catch {
      this.credentialSource = "missing";
    }
  }

  /** Start the immediate poll and arm the cadence (CONTRACT.md §3). */
  start() {
    if (this.disposed) return;
    this.refreshCredentialSource();
    void this.cycle().finally(() => this.armNext(this.intervalMs()));
  }

  /** Clear timers and abort an in-flight cycle; called from the ctx.effect disposer. */
  stop() {
    this.disposed = true;
    this.clearTimer();
    try {
      this.cycleAbort?.abort();
    } catch {
      /* already aborted */
    }
  }

  /** Re-apply a validated config: re-arm the timer with the new cadence. */
  applyConfig(config) {
    this.config = config;
    this.clearTimer();
    if (!this.disposed) this.armNext(this.intervalMs());
    this.persistState();
  }

  /* ---- poll loop ---- */

  /** Arm the next cycle; a completion-triggered re-arm keeps cycles from overlapping. */
  armNext(delayMs) {
    if (this.disposed) return;
    this.clearTimer();
    const timer = setTimeout(() => {
      this.timer = undefined;
      void this.cycle().finally(() => this.armNext(this.intervalMs()));
    }, Math.max(1_000, delayMs));
    if (typeof timer.unref === "function") timer.unref();
    this.timer = timer;
  }

  /** Clear the pending timer, if any. */
  clearTimer() {
    if (this.timer !== undefined) {
      clearTimeout(this.timer);
      this.timer = undefined;
    }
  }

  /**
   * One poll cycle: 4 sequential calls (balance + 24h/7d/30d usage), all-or-
   * nothing into the snapshot. A concurrent call joins the running cycle
   * (CONTRACT.md §3/§4.3). Never rejects.
   */
  cycle() {
    if (this.inFlight) return this.cyclePromise ?? Promise.resolve();
    if (this.disposed) return Promise.resolve();
    this.inFlight = true;
    const controller = new AbortController();
    this.cycleAbort = controller;

    const running = (async () => {
      try {
        const resolved = resolveApiKey({
          apiKey: this.config.apiKey,
          apiKeyEnv: this.config.apiKeyEnv,
        });
        this.credentialSource = resolved.source;

        const attemptedAt = new Date().toISOString();
        if (resolved.key === null) {
          // Quiet error state, never a throw (CONTRACT.md §3).
          this.lastPollAt = attemptedAt;
          this.lastPollOk = false;
          this.lastError = MISSING_CREDENTIAL;
          this.persistState();
          return;
        }

        // Sequential on purpose: 4 calls per cycle against a 10 req/min limit.
        const apiBase = this.config.apiBase;
        const signal = controller.signal;
        const balance = await fetchJsonDocument(apiUrl(apiBase, "/api/balance"), resolved.key, signal);
        const usage24 = await fetchJsonDocument(usageUrl(apiBase, "24h"), resolved.key, signal);
        const usage7 = await fetchJsonDocument(usageUrl(apiBase, "7d"), resolved.key, signal);
        const usage30 = await fetchJsonDocument(usageUrl(apiBase, "30d"), resolved.key, signal);

        if (this.disposed) return;
        const finishedAt = new Date().toISOString();
        // All four succeeded: replace the snapshot atomically (in memory).
        this.balanceRaw = balance;
        this.usageRaw = { "24h": usage24, "7d": usage7, "30d": usage30 };
        this.snapshotAt = finishedAt;
        this.lastPollAt = finishedAt;
        this.lastPollOk = true;
        this.lastError = null;
        this.persistState();
      } catch (error) {
        if (this.disposed) return;
        // A failed cycle keeps the previous snapshot and records the reason.
        this.lastPollAt = new Date().toISOString();
        this.lastPollOk = false;
        this.lastError = truncate(errorMessage(error), 200);
        this.persistState();
      } finally {
        this.inFlight = false;
        this.cyclePromise = undefined;
        this.cycleAbort = null;
      }
    })();

    this.cyclePromise = running;
    return running;
  }

  /** Force one poll now; joins an in-flight cycle (CONTRACT.md §4.3). */
  refresh() {
    return this.cycle();
  }

  /* ---- persistence ---- */

  /** Persisted document: settings + last snapshot + poll facts. Never the key. */
  stateDocument() {
    return {
      version: 1,
      savedAt: new Date().toISOString(),
      config: this.publicConfig(),
      snapshot: {
        asOf: this.snapshotAt,
        poll: {
          lastPollAt: this.lastPollAt,
          lastPollOk: this.lastPollOk,
          lastError: this.lastError,
        },
        balance: this.balanceRaw,
        usage: this.usageRaw,
      },
    };
  }

  persistState() {
    writeStateFile(this.statePath, this.stateDocument());
  }

  /* ---- views ---- */

  hasSnapshot() {
    return this.balanceRaw !== null;
  }

  rawRange(range) {
    return isObject(this.usageRaw) ? this.usageRaw[range] ?? null : null;
  }

  balanceView(nowMs) {
    return summarizeBalance(this.balanceRaw, { asOf: this.snapshotAt, nowMs });
  }

  pollView() {
    return {
      intervalMin: this.config.pollIntervalMin,
      lastPollAt: this.lastPollAt,
      lastPollOk: this.lastPollOk,
      lastError: this.lastError,
      inFlight: this.inFlight,
    };
  }

  /** `{ ok:false, status, message }` for a route that has no snapshot yet. */
  emptyStateBody() {
    const credentialMissing =
      this.credentialSource === "missing" || this.lastError === MISSING_CREDENTIAL;
    if (credentialMissing) {
      return {
        ok: false,
        status: "no-credential",
        message:
          "No Ollama Cloud API credential was found (set OLLAMA_CLOUD_API_KEY or add it to $DSH_HOME/.credentials.yaml).",
      };
    }
    return {
      ok: false,
      status: "no-data",
      message:
        this.lastError !== null
          ? `No Ollama Cloud data yet: ${this.lastError}`
          : "Waiting for the first Ollama Cloud poll to finish.",
    };
  }

  /** §4.1 overview document, or the quiet no-data envelope. */
  overview() {
    if (!this.hasSnapshot()) return this.emptyStateBody();
    const nowMs = Date.now();
    return {
      ok: true,
      generatedAt: new Date(nowMs).toISOString(),
      poll: this.pollView(),
      balance: this.balanceView(nowMs),
      usage: {
        "24h": summarizeUsage(this.rawRange("24h")),
        "7d": summarizeUsage(this.rawRange("7d")),
        "30d": summarizeUsage(this.rawRange("30d")),
      },
      config: this.publicConfig(),
    };
  }

  /** §4.2 status document, or the quiet no-data envelope. */
  status() {
    if (!this.hasSnapshot()) return this.emptyStateBody();
    const nowMs = Date.now();
    return summarizeStatus({
      balance: this.balanceView(nowMs),
      usage: {
        "24h": summarizeUsage(this.rawRange("24h")),
        "7d": summarizeUsage(this.rawRange("7d")),
        "30d": summarizeUsage(this.rawRange("30d")),
      },
      poll: this.pollView(),
      config: this.publicConfig(),
      nowMs,
    });
  }

  /** §4.4 one UsageRange, or the quiet no-data envelope. */
  usage(range) {
    if (!this.hasSnapshot()) return this.emptyStateBody();
    const summary = summarizeUsage(this.rawRange(range));
    if (summary === null) {
      return { ok: false, status: "no-data", message: `No usage data for ${range} yet.` };
    }
    return summary;
  }
}

/* -------------------------------------------------------------------------- */
/* §4 — HTTP helpers and routes                                                */
/* -------------------------------------------------------------------------- */

/** Send one JSON response with the frozen content type and no-store caching. */
function sendJson(res, status, body, extraHeaders) {
  const text = JSON.stringify(body);
  const headers = {
    "content-type": "application/json; charset=utf-8",
    "cache-control": "no-store",
    "content-length": String(Buffer.byteLength(text)),
    ...(extraHeaders ?? {}),
  };
  if (res.headersSent) {
    res.end(text);
    return;
  }
  res.writeHead(status, headers);
  res.end(text);
}

/** Send the fence's exact plain-text denial. */
function sendForbidden(res) {
  const text = "forbidden";
  if (res.headersSent) {
    res.end(text);
    return;
  }
  res.writeHead(403, {
    "content-type": "text/plain; charset=utf-8",
    "cache-control": "no-store",
    "content-length": String(Buffer.byteLength(text)),
  });
  res.end(text);
}

/**
 * Build one exact-path route handler: fence first, then the expected method,
 * then the route body. Any unexpected throw becomes a JSON 500 instead of an
 * unhandled rejection in the webserver.
 *
 * @param ctx - host context (trust sources are read per request via `ctx.get`).
 * @param method - the one accepted HTTP method for this route.
 * @param handle - `async (req, res)` route body.
 * @returns a node `(req, res)` handler.
 */
function makeRouteHandler(ctx, method, handle) {
  return async function creditsRouteHandler(req, res) {
    try {
      if (!isTrustedRequest(req ?? {}, () => deploymentTrustedHosts(ctx))) {
        sendForbidden(res);
        return;
      }
      const actualMethod = String(req?.method ?? "GET").toUpperCase();
      if (actualMethod !== method) {
        sendJson(
          res,
          405,
          { ok: false, error: "METHOD_NOT_ALLOWED", message: `${method} required` },
          { allow: method },
        );
        return;
      }
      await handle(req, res);
    } catch (error) {
      if (res.headersSent) {
        try {
          res.destroy();
        } catch {
          /* response already gone */
        }
        return;
      }
      sendJson(res, 500, { ok: false, error: "INTERNAL", message: errorMessage(error) });
    }
  };
}

/** Parse `?range=` for §4.4; absent/empty -> "7d", anything else -> null (400). */
function parseUsageRange(url) {
  let params;
  try {
    params = new URL(String(url ?? ""), "http://dsh.invalid").searchParams;
  } catch {
    return null;
  }
  const raw = params.get("range");
  if (raw === null || raw === "") return "7d";
  return USAGE_RANGES.includes(raw) ? raw : null;
}

/** Read a bounded JSON object body for POST /config. */
async function readJsonObjectBody(req, maxBytes = CONFIG_BODY_MAX_BYTES) {
  const chunks = [];
  let size = 0;
  try {
    for await (const chunk of req ?? []) {
      const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      size += buffer.length;
      if (size > maxBytes) return { ok: false, message: "request body is too large" };
      chunks.push(buffer);
    }
  } catch {
    return { ok: false, message: "request body could not be read" };
  }
  const text = Buffer.concat(chunks).toString("utf8").trim();
  if (text === "") return { ok: true, value: {} };
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { ok: false, message: "request body is not valid JSON" };
  }
  if (!isObject(parsed)) return { ok: false, message: "request body must be a JSON object" };
  return { ok: true, value: parsed };
}

/**
 * Build the five frozen route registrations (CONTRACT.md §4).
 *
 * @param ctx - host context.
 * @param service - the row's runtime.
 * @returns `{ kind:'exact', path, handler }` records for `ctx.webServer.register`.
 */
function buildRoutes(ctx, service) {
  return [
    {
      kind: "exact",
      path: ROUTES.overview,
      handler: makeRouteHandler(ctx, "GET", async (req, res) => {
        sendJson(res, 200, service.overview());
      }),
    },
    {
      kind: "exact",
      path: ROUTES.status,
      handler: makeRouteHandler(ctx, "GET", async (req, res) => {
        sendJson(res, 200, service.status());
      }),
    },
    {
      kind: "exact",
      path: ROUTES.refresh,
      handler: makeRouteHandler(ctx, "POST", async (req, res) => {
        await service.refresh();
        sendJson(res, 200, service.overview());
      }),
    },
    {
      kind: "exact",
      path: ROUTES.usage,
      handler: makeRouteHandler(ctx, "GET", async (req, res) => {
        const range = parseUsageRange(req?.url);
        if (range === null) {
          sendJson(res, 400, {
            ok: false,
            error: "BAD_RANGE",
            message: `range must be one of ${USAGE_RANGES.join(", ")}`,
          });
          return;
        }
        sendJson(res, 200, service.usage(range));
      }),
    },
    {
      kind: "exact",
      path: ROUTES.config,
      handler: makeRouteHandler(ctx, "POST", async (req, res) => {
        const body = await readJsonObjectBody(req);
        if (!body.ok) {
          sendJson(res, 400, { ok: false, error: "BAD_CONFIG", message: body.message });
          return;
        }
        const validated = validateConfig(body.value, { base: service.config });
        if (!validated.ok) {
          sendJson(res, 400, {
            ok: false,
            error: "BAD_CONFIG",
            message: validated.message,
          });
          return;
        }
        service.applyConfig(validated.config);
        sendJson(res, 200, { ok: true, config: service.publicConfig() });
      }),
    },
  ];
}

/* -------------------------------------------------------------------------- */
/* Plugin                                                                      */
/* -------------------------------------------------------------------------- */

/**
 * Mount the poller and the five routes (CONTRACT.md §3/§4).
 *
 * Defensive by contract: a bad config, a missing credential, a register failure
 * or a throwing service lookup can never throw out of `apply` into the Loader.
 * Registered routes and the poll timer are disposed together through
 * `ctx.effect`.
 *
 * @param ctx - host plugin context carrying `webServer` (and `get`/`effect`).
 * @param config - optional row config (CONTRACT.md §3 table).
 */
export function apply(ctx, config) {
  try {
    const dshHome = resolveDshHome(process.env);

    let validated = validateConfig(config, { dshHome });
    let effective;
    if (validated.ok) {
      effective = validated.config;
    } else {
      safeLog(
        ctx,
        "warn",
        `dsh-ollama-credits: invalid config (${validated.message}); using defaults`,
      );
      effective = validateConfig(undefined, { dshHome }).config;
    }

    const statePath = join(effective.stateDir, "state.json");
    const persisted = loadStateFile(statePath);

    // Persisted user settings (POST /config) survive a restart; they win over
    // the row defaults, but a corrupt patch is ignored rather than fatal.
    if (isObject(persisted?.config)) {
      const merged = validateConfig(persisted.config, { base: effective, dshHome });
      if (merged.ok) effective = merged.config;
    }

    const service = new OllamaCreditsService(ctx, effective, statePath, persisted);

    const mount = () => {
      const disposers = [];
      const webServer = ctx?.webServer;
      if (typeof webServer?.register === "function") {
        let routes = [];
        try {
          routes = buildRoutes(ctx, service);
        } catch (error) {
          safeLog(ctx, "warn", `dsh-ollama-credits: route build failed: ${errorMessage(error)}`);
        }
        for (const route of routes) {
          try {
            const dispose = webServer.register(route);
            if (typeof dispose === "function") disposers.push(dispose);
          } catch (error) {
            safeLog(
              ctx,
              "warn",
              `dsh-ollama-credits: failed to register ${route.path}: ${errorMessage(error)}`,
            );
          }
        }
      } else {
        safeLog(ctx, "warn", "dsh-ollama-credits: webServer.register is unavailable; no routes mounted");
      }

      service.start();
      return () => {
        for (const dispose of disposers) {
          try {
            dispose();
          } catch {
            /* route fiber already gone during shutdown */
          }
        }
        service.stop();
      };
    };

    if (typeof ctx?.effect === "function") {
      try {
        ctx.effect(mount, "dsh-ollama-credits: poller + routes");
      } catch (error) {
        safeLog(ctx, "warn", `dsh-ollama-credits: ctx.effect failed: ${errorMessage(error)}`);
        try {
          mount();
        } catch (mountError) {
          safeLog(ctx, "warn", `dsh-ollama-credits: mount failed: ${errorMessage(mountError)}`);
        }
      }
    } else {
      try {
        mount();
      } catch (error) {
        safeLog(ctx, "warn", `dsh-ollama-credits: mount failed: ${errorMessage(error)}`);
      }
    }
  } catch (error) {
    // Last line of defence: the Loader must never see this row throw.
    safeLog(ctx, "warn", `dsh-ollama-credits: apply failed: ${errorMessage(error)}`);
  }
}
